import numpy as np
def basis(fun_t):
    cols=[]
    for pw in [P**0,P,P**2,P**3]:
        for tt in [np.ones_like(t),t,fun_t]:
            cols.append(pw*tt)
    return np.array(cols).T
best=[]
for b in np.linspace(0.05,3,120):
    for name,f in [('tanh',np.tanh(b*t)),('exp',np.exp(-b*t)),('1-exp',1-np.exp(-b*t))]:
        A=basis(f)
        c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
        r=dP_dt-A@c
        best.append((np.mean(r**2)/np.var(dP_dt),name,round(b,3)))
best.sort()
print(best[:8])

